cat > tmp/smoke.ts <<'EOF'
import { prisma } from '../src/db.js';

const u = await prisma.user.create({
  data: { username: 'smoke_u', email: 'smoke@example.com', passwordHash: 'x' },
});
const a = await prisma.article.create({
  data: {
    slug: 'smoke-slug', title: 'T', description: 'D', body: 'B', authorId: u.id,
    tags: {
      create: [
        { order: 0, tag: { create: { name: 'zeta' } } },
        { order: 1, tag: { create: { name: 'alpha' } } },
      ],
    },
  },
});
const found = await prisma.article.findUniqueOrThrow({
  where: { id: a.id },
  include: { tags: { include: { tag: true } }, author: true, _count: { select: { favorites: true } } },
});
const tagList = [...found.tags].sort((x, y) => x.order - y.order).map((t) => t.tag.name);
console.log('tagList:', tagList, 'author:', found.author.username, 'favs:', found._count.favorites);
if (JSON.stringify(tagList) !== JSON.stringify(['zeta', 'alpha'])) throw new Error('order not preserved');
await prisma.article.delete({ where: { id: a.id } });
await prisma.user.delete({ where: { id: u.id } });
await prisma.tag.deleteMany({ where: { name: { in: ['zeta', 'alpha'] } } });
console.log('OK');
await prisma.$disconnect();
EOF
npx tsx tmp/smoke.ts 2>&1 | tail -10
